import csv
from pathlib import Path


def answer() -> int:
    # Przemysław Kurczab is Dawid Majtyka's great-great-grandparent.
    # Among Przemysław's direct children, Liwia Maligłówka and Alan Wocial
    # each have more than one grandchild in the lineage diagram.
    qualifying_children = {
        ("Liwia", "Maligłówka"),
        ("Alan", "Wocial"),
    }

    with Path("/app/dataset/people_accounts.csv").open(
        newline="", encoding="utf-8"
    ) as accounts_file:
        accounts = csv.DictReader(accounts_file)
        return sum(
            int(row["account_balance"])
            for row in accounts
            if (row["first_name"], row["last_name"]) in qualifying_children
        )


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w", encoding="utf-8") as answer_file:
        json.dump(answer(), answer_file, default=list)
